import {CHARS,LEVELS,UPGRADES,OPENING,ENDING,STAT_NAMES} from './campaign.mjs';
import {newCampaign,newRun,available,actorJob,dependenciesMet,start,plan,dispatch,recall,tick,skill,buyTools,rating,commitWin,buyUpgrade,finishNow} from './simulation.mjs';
import {Sound} from './sound.mjs';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=id=>globalThis.ABSTRACT_ASSETS?.[id]||`./assets/${id}.webp`;
const who=id=>id==='dispatch'?'调度员':id==='system'?'规程系统':CHARS.find(c=>c.id===id)?.name||id;
const ICONS={lift:'↕',fire:'♨',crowd:'♟',drone:'✣',screen:'▣',bridge:'⌁',stage:'★',boss:'⚙'};
const SAVE='abstract-dispatch-campaign-v2',SETTINGS='abstract-dispatch-settings-v2';
let campaign=newCampaign(),settings={master:.8,music:.35,voice:.95,subtitles:true,motion:true},phase='menu',run=null,selectedJob=null,crew=[],route='safe',difficulty='standard',paused=true,speed=1,overlayKind='',pending=[],story=null,storyTime=0,storyDuration=10,storyIndex=0,storyThen=null,storyTitle='',beatElapsed=0,lastFrame=performance.now(),toastTimer,tutorial=-1,resultRecord=null,stageReward=null,oldPositions={};
try{const c=JSON.parse(localStorage.getItem(SAVE));if(c?.version===2&&Array.isArray(c.stars)&&c.stars.length===6&&Number.isInteger(c.unlocked)&&c.unlocked>=0&&c.unlocked<=5)campaign=c;const set=JSON.parse(localStorage.getItem(SETTINGS));if(set)for(const k in settings)if(typeof set[k]===typeof settings[k])settings[k]=set[k];}catch{}
for(const k of ['master','music','voice'])settings[k]=Math.max(0,Math.min(1,settings[k]));
const audio=new Sound(settings);
function save(){try{if(run&&phase==='play'&&!run.finished)campaign.run=structuredClone({...run,checkpoint:null,uiTutorial:tutorial,uiJob:selectedJob});localStorage.setItem(SAVE,JSON.stringify(campaign));localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch{}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function clock(t=run?.turn||0){return `${String(20+Math.floor(t*4/60)).padStart(2,'0')}:${String(t*4%60).padStart(2,'0')}`;}
function setPhase(next){phase=next;overlayKind='';$('#overlay').innerHTML='';audio.stopVoice();beatElapsed=0;render();save();}
function menu(){phase='menu';run=null;overlayKind='';$('#overlay').innerHTML='';audio.stopVoice();render();}
function render(){if(phase==='menu')renderMenu();if(phase==='chapters')renderChapters();if(phase==='prep')renderPrep();if(phase==='story')renderStory();if(phase==='play')renderPlay();if(phase==='debrief')renderDebrief();if(phase==='credits')renderCredits();document.documentElement.classList.toggle('reduce-motion',!settings.motion);}
function renderMenu(){
 const done=campaign.stars.filter(n=>n>0).length;
 $('#game').innerHTML=`<main class="screen menu"><img class="menu-bg" src="${asset('intro-city')}" alt="雨夜抽象区的美漫城市"><div class="menu-shade"></div><div class="menu-content"><div class="wordmark"><span class="mark">派</span><div>抽象派遣局<div class="eyebrow" style="margin-top:5px;font-size:8px">THE NIGHT SHIFT / STORY CAMPAIGN</div></div></div><h1 class="menu-title">今晚<br><span>谁背锅。</span></h1><div class="menu-sub">一晚，五区，八个不太靠谱的人。<br>先把人救了，账单天亮再说。</div><div class="menu-actions"><button class="menu-button primary" data-a="new"><span>开始新战役</span><small>NEW GAME →</small></button><button class="menu-button" data-a="continue" ${done||campaign.run?'':'disabled'}><span>继续夜班</span><small>${campaign.run?'进行中的任务':done+'/6 档案完成'}</small></button><button class="menu-button" data-a="chapters"><span>关卡档案 / 休息室</span><small>CASE FILES</small></button><button class="menu-button" data-a="settings"><span>声音与设置</span><small>OPTIONS</small></button></div></div><div class="menu-sticker">专业的人没来。<small>来的这几位，多少有点特长。</small></div><div class="menu-footer">完整战役试玩 · 动态漫画与中文配音 · 电脑横屏体验更佳</div></main>`;
}
function renderChapters(){
 $('#game').innerHTML=`<main class="screen chapter-screen"><div class="page-top row spread"><div><div class="eyebrow">CASE FILES / ${campaign.stars.filter(n=>n>0).length} OF 6 COMPLETED</div><h1>天亮之前，<br>把这几份档案销了。</h1></div><button class="btn ghost" data-a="menu">← 主菜单</button></div><div class="chapter-layout"><div><div class="chapter-grid">${LEVELS.map(l=>`<button class="chapter-card ${l.id>campaign.unlocked?'locked':''}" data-a="chapter" data-level="${l.id}" ${l.id>campaign.unlocked?'disabled':''}><img src="${asset(l.image)}" alt="${esc(l.district)}美漫关卡背景"><span class="chapter-num">${l.id===0?'LAB':'0'+l.id}</span><div class="chapter-text"><h3>${l.name}</h3><p>${l.mechanic}</p><div class="row spread"><span class="stars">${'★'.repeat(campaign.stars[l.id])}${'☆'.repeat(3-campaign.stars[l.id])}</span><span class="small">${l.id>campaign.unlocked?'尚未解锁':campaign.stars[l.id]?'重玩 ↗':'进入 ↗'}</span></div></div></button>`).join('')}</div><div class="chapter-note">三星：处理全部事件；设备损失不超过关卡编号+1（至少2），且城市压力低于25。重玩提高星级可追加津贴，重复通关不会重复发钱。</div></div><aside class="shop"><div class="row spread"><div class="eyebrow">BREAK ROOM</div><span class="shop-bank">${campaign.bank}<small style="font-size:10px"> 津贴</small></span></div><h2>先把工位升级了。</h2><p class="small">改造永久生效。本战役无需购买改造也能通关。</p>${UPGRADES.map(u=>`<div class="upgrade"><strong>${u.name}</strong><p>${u.text}</p><button class="btn" data-a="upgrade" data-id="${u.id}" ${campaign.upgrades.includes(u.id)||campaign.bank<u.cost?'disabled':''}>${campaign.upgrades.includes(u.id)?'已装好 ✓':'花 '+u.cost+' 津贴改造'}</button></div>`).join('')}<div class="credits-note">这是游戏内津贴，不涉及任何真实付费。<br>角色原画、剧情配音与全部关卡均可离线运行。</div></aside></div></main>`;
}
function chooseChapter(id,replayStory=true){
 if(id>campaign.unlocked)return;run=newRun(id,campaign,difficulty);crew=[];selectedJob=run.jobs[0].id;route='safe';tutorial=id===0&&campaign.stars[0]===0?0:-1;oldPositions={};
 if(replayStory)beginStory(LEVELS[id].story,()=>{phase='prep';render();},LEVELS[id].name);else setPhase('prep');
}
function renderPrep(){const l=LEVELS[run.level];$('#game').innerHTML=`<main class="screen prep-screen"><div class="page-top row spread"><div><div class="eyebrow">${l.district} / PREPARE YOUR CREW</div><h1>${l.name}</h1><div class="small">${l.mechanic}</div></div><button class="btn ghost" data-a="chapters">← 档案</button></div><div class="prep-layout"><div class="prep-grid">${CHARS.map(c=>{const unlocked=l.unlock.includes(c.id),selected=run.duty.includes(c.id);return `<article class="prep-card ${selected?'selected':''} ${unlocked?'':'locked'}" style="--c:${c.color}"><button class="clean" style="display:block;width:100%;text-align:left" data-a="roster" data-id="${c.id}" ${!unlocked||run.level===0?'disabled':''}><img src="${asset(c.id)}" alt="${c.name}角色立绘">${selected?'<span class="selected-mark">✓</span>':''}<div class="prep-info"><strong>${c.name}</strong><small>${unlocked?c.title:'后续剧情加入'}</small><small>✦ ${c.ability.name}</small></div></button><button class="clean small" style="padding:0 10px 10px" data-a="profile" data-id="${c.id}">角色与技能 ↗</button></article>`}).join('')}</div><aside class="prep-aside"><div class="eyebrow">MISSION BRIEFING / ${run.duty.length} OF ${l.squad}</div><h2>今晚带谁去？</h2><div class="objective">完成至少 <b>${l.minComplete} / ${l.jobs.length}</b> 单。<br>所有标有 <b style="color:var(--red)">!</b> 的关键任务必须完成。<br>城市压力达到100，或时间耗尽且目标未达成，任务失败。</div><div class="prep-stats"><div><b>${run.budget}</b><span>开局预算</span></div><div><b>${run.tools}</b><span>工具包</span></div><div><b>${run.energy}</b><span>指挥点</span></div><div><b>${l.slots}</b><span>同时出警线路</span></div></div><div class="small">选择难度</div><div class="difficulty"><button class="btn ${difficulty==='relaxed'?'active':''}" data-a="difficulty" data-mode="relaxed">轻松 · 多2拍</button><button class="btn ${difficulty==='standard'?'active':''}" data-a="difficulty" data-mode="standard">标准</button></div><p class="small" style="line-height:1.9">每单1到2人。出发要1拍，完成后还要返程。技能消耗指挥点，每3拍恢复1点。疲劳≥3会降低属性。</p><button class="btn primary big" data-a="launch" ${run.duty.length!==l.squad?'disabled':''}>${run.level===0?'进入实验关':'开始出警'} <span class="arrow">→</span></button><div class="small" style="font-size:9px;margin-top:15px">空格可随时暂停。暂停时也能规划、派人和使用技能。</div></aside></div></main>`;}
function beginStory(panels,then,title){clearTimeout(toastTimer);$('#toast').classList.remove('show');audio.init();story=panels;storyThen=then;storyTitle=title;storyIndex=0;phase='story';overlayKind='';$('#overlay').innerHTML='';openStoryPanel();}
function openStoryPanel(){storyTime=0;storyDuration=Math.max(7,story[storyIndex].text.length/4.1+1.5);renderStory();audio.fx('paper');audio.play(story[storyIndex].audio,{onmeta:d=>{if(d>1&&Number.isFinite(d))storyDuration=Math.max(5,d+.8);}});}
function nextStory(){audio.stopVoice();if(storyIndex<story.length-1){storyIndex++;openStoryPanel();}else{const done=storyThen;story=null;done?.();save();}}
function skipStory(){audio.stopVoice();const done=storyThen;story=null;done?.();save();}
function renderStory(){const p=story[storyIndex];$('#game').innerHTML=`<main class="screen story"><img class="story-bg" src="${asset(p.image)}" alt="${esc(p.speaker)}的美漫剧情镜头" style="animation-duration:${storyDuration+2}s"><div class="story-shade"></div>${p.actor?`<div class="story-actor"><img src="${asset(p.actor==='tim'?'tim-focused':p.actor)}" alt="${esc(p.speaker)}现场特写"></div>`:''}<div class="story-top"><span class="story-count">${esc(storyTitle)} / ${String(storyIndex+1).padStart(2,'0')} OF ${String(story.length).padStart(2,'0')}</span><div class="row"><button class="btn" data-a="settings">声音</button><button class="btn" data-a="skip-story">跳过本段 ↗</button></div></div>${storyTitle==='序幕：今晚谁背锅'&&storyIndex===0?'<div class="story-title">抽象派遣局<br><span>今晚，谁背锅。</span></div>':''}<div class="story-caption" ${settings.subtitles?'':'style="display:none"'}><span class="story-speaker">${esc(p.speaker)}</span><div class="story-text" id="story-text" aria-live="polite">${esc(p.text.match(/[^。！？]+[。！？]?/g)?.[0]||p.text)}</div></div><div class="story-progress">${story.map((_,i)=>`<div><span class="story-segment" style="width:${i<storyIndex?100:0}%"></span></div>`).join('')}</div><span class="voice-label">中文剧情配音 / 原创角色声线</span><div class="story-next"><button data-a="next-story">下一格 → / SPACE</button></div></main>`;}
function actorState(id){const a=run.actors[id],j=actorJob(run,id);if(j)return j.travelLeft?'赶往现场':'处理 '+j.workLeft+'格';if(a.returnUntil>run.turn)return '返程 '+(a.returnUntil-run.turn)+'拍';if(a.fatigue>=6)return '休息中';return '待命';}
function taskLabel(j){return {queued:'第'+j.release+'拍接入',waiting:'待处理',locked:'前置未完成',active:j.travelLeft?'出发中':'处理 '+j.workLeft+'格',done:'已解决',failed:'失败，可补救',expired:'撤单，可补救'}[j.status];}
function skillLabel(c){if(c.id==='da'&&run.rewindUsed)return '本关已用';if(run.actors[c.id].cooldown>run.turn)return '冷却 '+(run.actors[c.id].cooldown-run.turn);return '✦ '+c.ability.name+' · '+c.ability.cost;}
function guideText(){const steps=[['先接一通电话','点地图上的「训练电梯卡住了」。红色任务需要你派人。'],['把技术人员叫上','点左侧何彤学的头像。他的技术足够处理这单。'],['按下出发','右侧显示实际耗时和费用。点「出发」，派他去修。'],['先让他到现场','实验关不会自动走时间。点底部「单步一拍」。'],['试一次主动技能','何彤学已到现场。点他卡片上的「开源加速」，用1工具和1指挥点赶工。'],['技能已经生效','工作已推进2格，再走1拍就能完成。关闭现场报告后，继续单步到第3拍接工具箱任务。'],['换一个合适的人','点地图上的工具箱，再点首工耿。他适合搬重物。'],['派出去，再等他回来','选择稳妥方案，点出发，再单步推进。处理和返程是两段不同的时间。']];return steps[Math.min(tutorial,7)];}
function renderPlay(){
 const l=LEVELS[run.level],j=run.jobs.find(j=>j.id===selectedJob)||run.jobs.find(j=>j.status==='waiting')||run.jobs[0];selectedJob=j.id;
 const p=crew.length&&['waiting','locked'].includes(j.status)?plan(run,j,crew,route):null,active=run.jobs.filter(j=>j.status==='active').length;
 const canStart=p&&!p.blocked&&p.fee<=run.budget&&p.tools<=run.tools&&active<l.slots;
 const eventForecast=l.events.filter(e=>e.at>run.turn&&e.at<=run.forecastUntil);
 $('#game').innerHTML=`<main class="screen play-screen ${tutorial>=0?'tutoring':''}"><header class="hud"><div class="hud-brand">抽象派遣局<small>THE NIGHT SHIFT</small></div><div class="hud-chapter"><strong>${run.level===0?'LAB':'0'+run.level} / ${l.name}</strong><small>${paused?'战术暂停 · 可操作':'实时出警 · '+speed+'倍速'} · ${l.district}</small></div><div class="resources"><div class="resource lime"><small>预算</small>${run.budget}</div><div class="resource"><small>工具包</small>${run.tools}</div><div class="resource cyan"><small>指挥点</small>${run.energy}<span style="font-size:10px;color:var(--muted)">/${run.maxEnergy}</span></div><div class="resource ${run.panic>55?'red':''}"><small>城市压力</small>${run.panic}<span style="font-size:10px">%</span></div></div><button class="btn ghost" data-a="help">?</button><button class="btn ghost" data-a="pause-menu">Ⅱ 菜单</button></header><div class="play-layout"><aside class="crew-column"><div class="side-head">值班队伍 <small>${run.duty.filter(id=>available(run,id)).length} READY</small></div><div class="crew-list">${run.duty.map(id=>{const c=CHARS.find(c=>c.id===id),a=run.actors[id],ready=available(run,id),selected=crew.includes(id),skillDisabled=a.cooldown>run.turn||run.energy<c.ability.cost||(id==='da'&&run.rewindUsed);return `<article class="crew-card ${selected?'selected':''} ${ready?'':'unavailable'} ${tutorial===1&&id==='he'?'guided':''}" style="--c:${c.color}"><button class="crew-main" data-a="crew" data-id="${id}" aria-label="选择${c.name}出勤"><div class="crew-pic"><img data-face="${id}" data-face-state="${id}" src="${asset(id)}" alt="${c.name}"><span class="crew-status">${actorState(id)}</span>${selected?'<span class="crew-check">✓</span>':''}</div><div class="crew-info"><strong>${c.name}</strong><div class="fatigue-bar" title="疲劳${a.fatigue}/6"><span style="width:${a.fatigue/6*100}%"></span></div></div></button><button class="crew-detail" data-a="profile" data-id="${id}" aria-label="查看${c.name}档案">↗</button><button class="crew-skill ${tutorial===4&&id==='he'?'guided':''}" data-a="skill" data-id="${id}" title="${esc(c.ability.text)}" ${skillDisabled?'disabled':''}>${skillLabel(c)}</button></article>`}).join('')}</div><div class="crew-note">头像选人，↗看属性。<br>疲劳3：属性-1；疲劳6：必须休息。<br>队员回到基地后每拍恢复疲劳。</div></aside><section class="field-column"><div class="field-map" id="field-map"><img class="field-bg" src="${asset(l.image)}" alt="${l.district}现场地图">${mapSvg()}<div class="map-label"><div class="eyebrow">LIVE / SECTOR ${String(run.level).padStart(2,'0')}</div><b>${l.district.split('/')[1]?.trim()||'实验场'}</b></div><div class="map-signal"></div>${run.level===3?'<div class="rain"></div>':''}<div class="map-object-layer">${run.jobs.filter(q=>q.status!=='queued').map(q=>`<button class="map-pin ${q.status} ${q.id===j.id?'current':''} ${q.critical?'critical':''} ${tutorial===0&&q.id==='lab-door'?'guided':''}" style="left:${q.point[0]}%;top:${q.point[1]}%" data-a="job" data-id="${q.id}" aria-label="任务：${esc(q.title)}">${q.status==='done'?'✓':q.status==='locked'?'⌑':ICONS[q.type]}</button><span class="map-pin-label" style="left:${q.point[0]}%;top:${q.point[1]}%">${esc(q.title)}</span>`).join('')}${mapUnits()}<span class="hq">派遣局 / HQ</span></div><div class="map-corner">✦ N &nbsp; ━ 200m</div>${run.shield||eventForecast.length?`<div class="forecast">${run.shield?'质检护盾 ×'+run.shield+'<br>':''}${eventForecast.map(e=>'第'+e.at+'拍：'+({surge:'自动催单',drain:'指挥点扣除',blackout:'低功耗模式',jam:'返程拥堵'}[e.kind])).join('<br>')||'已完成近期事件复核'}</div>`:''}<div class="status-bands">${run.blackoutUntil>run.turn?`<span class="status-band">低功耗：剩${run.blackoutUntil-run.turn}拍</span>`:''}${run.jamUntil>run.turn?`<span class="status-band">返程拥堵：剩${run.jamUntil-run.turn}拍</span>`:''}${run.rewindUsed?'<span class="status-band">回溯已使用</span>':''}</div></div><section class="radio-box"><div class="radio-title"><span>◉ 无线电 / CH.07</span><span>${audio.voice?'<i class="voice-pulse"><i></i><i></i><i></i></i>':'LIVE'}</span></div><div class="radio-lines" role="log">${run.log.slice(-6).map(x=>`<div class="radio-line"><time>${clock(x.at)}</time><b>${who(x.who)}</b>${esc(x.text)}</div>`).join('')||'<div class="small">频道接通。等一通不太省心的电话。</div>'}</div></section></section><aside class="orders-column"><div class="objective-banner"><b>目标 ${run.completed}/${l.minComplete}</b>　·　全部关键任务必须完成<br><span class="critical-dot">!</span> 关键任务 ${run.jobs.filter(q=>q.critical&&q.status==='done').length}/${run.jobs.filter(q=>q.critical).length}　·　出警线路 ${active}/${l.slots}</div><div class="ticket-list">${run.jobs.map(q=>`<button class="ticket-mini ${q.id===j.id?'current':''} ${q.status}" data-a="job" data-id="${q.id}"><strong>${q.critical?'! ':''}${esc(q.title)}</strong><small class="${['waiting','active','locked'].includes(q.status)&&q.deadline-run.turn<=3?'red':''}">${q.status==='queued'?'第'+q.release+'拍接入':q.status==='done'?'✓ 已解决':q.status==='active'?'出勤中':q.status==='failed'||q.status==='expired'?'× '+taskLabel(q):'剩'+Math.max(0,q.deadline-run.turn)+'拍'}</small></button>`).join('')}</div><section class="order-panel"><div class="row spread"><span class="eyebrow">CASE ${String(run.jobs.indexOf(j)+1).padStart(2,'0')}</span><span class="pill ${j.critical?'red':''}">${j.critical?'关键任务':'支线事件'}</span></div><h2>${esc(j.title)}</h2><div class="row spread"><span class="pill ${j.status==='active'?'cyan':j.status==='done'?'lime':''}">${taskLabel(j)}</span><span class="small">${['waiting','locked','active'].includes(j.status)?'剩 '+Math.max(0,j.deadline-run.turn)+' 拍':''}</span></div><p class="order-desc">${esc(j.desc)}</p>${j.dependencies.length?`<div class="dependencies">前置：${j.dependencies.map(id=>{const q=run.jobs.find(x=>x.id===id);return (q.status==='done'?'✓ ':'⌑ ')+q.title;}).join(' / ')}</div>`:''}${['waiting','locked'].includes(j.status)?`<div class="route-choices">${['safe','chaos'].map(m=>`<button class="route-choice ${route===m?'active':''}" data-a="route" data-mode="${m}"><strong>${m==='safe'?'稳妥处理':'放飞自我'}</strong>${j[m].name}</button>`).join('')}</div><div class="requirements">${Object.entries(j.hidden&&!j.revealed?j[route].req:(p?.req||j[route].req)).map(([k,n])=>`<span class="req ${j.hidden&&!j.revealed?'unknown':p?(p.stats[k]>=n?'ok':'bad'):''}">${STAT_NAMES[k]} ${p?p.stats[k]+'/':''}${j.hidden&&!j.revealed?n+' ?':n}${p&&j.revealed?(p.stats[k]>=n?' ✓':' ✕'):''}</span>`).join('')}</div>${j.hidden&&!j.revealed?'<div class="small" style="font-size:9px;color:#d7c78c">信息不全，实际要求可能更高。缇姆可侦察。</div>':''}<div class="selected-team">${crew.length?crew.map(id=>`<button class="team-chip" data-a="crew" data-id="${id}">${who(id)} ×</button>`).join(''):'← 点头像选人，最多2位'}</div>${p?`<div class="cost-grid"><div><span>出发+工作</span><b>${p.duration}拍</b></div><div><span>预算</span><b>${p.fee}</b></div><div><span>工具</span><b>${p.tools}</b></div><div><span>预计损失</span><b>${p.damage}</b></div></div><div class="plan-notes">${p.notes.map(esc).join(' · ')||'普通出勤，无额外修正。'}<br>${p.blocked?'⌑ 前置未完成':!p.known?'? 情报不足，结果未确认':p.success?'✓ 能力达标':'✕ 能力不足，预计失败'} · 预计第${run.turn+p.duration}拍结束${run.turn+p.duration>j.deadline?' / 普通速度超时，需赶工或控场':''}</div>`:''}<button class="btn primary deploy ${tutorial===2?'guided':''}" data-a="dispatch" ${canStart?'':'disabled'}><span>${!crew.length?'先选人':p?.blocked?'先处理前置任务':p?.tools>run.tools?'工具不足':p?.fee>run.budget?'预算不足':p&&run.turn+p.duration>j.deadline?'普通速度会超时，冒险出发':active>=l.slots?'出警线路占满':p?.known&&!p.success?'硬着头皮上':'就你们了，出发！'}</span><span>↗</span></button>`:j.status==='active'?`<div class="active-crew">${j.crew.map(id=>`<img data-face="${id}" data-face-state="${id}" src="${asset(id)}" alt="${who(id)}">`).join('')}</div><div class="active-info">${j.crew.map(who).join(' ＋ ')}<br>${j.travelLeft?'正在赶往现场。':'已经到场，剩 '+j.workLeft+' 格工作。'}${j.type==='boss'?'<br>⚠ 控制台会在半程反扑，留好指挥点。':''}</div><div class="progress-track"><span style="width:${Math.max(0,100*(1-(j.travelLeft+j.workLeft)/j.plan.duration))}%"></span></div><button class="btn ghost" data-a="recall" data-id="${j.id}" style="font-size:9px;padding:7px 9px">召回 · 不退费用和工具</button>`:j.status==='queued'?`<div class="active-info">第${j.release}拍接入。<br>先处理已接到的电话；别把所有人都派远了。</div>`:j.status==='done'?`<div class="active-info">✓ 已处理完成。<br>奖金 +${j.pay}${j.toolReward?' / 工具 +'+j.toolReward:''}</div><button class="btn ghost" style="margin-top:12px" data-a="replay" data-id="${j.id}">现场回放 ↗</button>`:`<div class="active-info">这单没处理好。${j.retryUsed?'已经使用过兜底。':'罗咏皓若在值班，可用售后兜底接回。'}</div><button class="btn ghost" style="margin-top:12px" data-a="skill" data-id="luo" ${!run.duty.includes('luo')?'disabled':''}>试试售后兜底</button>`}</section><div class="field-help">暂停时仍可派人和用技能。<br>返程不占出警线路，队员必须回基地才能再派。<br>工具不够：底部花3预算采购1包。</div></aside></div><footer class="control-bar"><div class="time-block"><strong>${clock()}</strong><small>第${run.turn} / ${run.maxTurns??l.turns}拍 · ${paused?'暂停中':'每拍6秒'}</small><div class="beat-meter"><span id="beat-meter"></span></div></div><div class="timeline">${Array.from({length:run.maxTurns??l.turns},(_,i)=>`<span class="tick-pip ${i<run.turn?'past':''} ${l.events.some(e=>e.at===i+1)?'event':''}" title="第${i+1}拍"></span>`).join('')}</div><div class="control-actions"><button class="btn hide-mobile" data-a="buy-tool" title="花3预算买1工具">工具 +1 / 3预算</button><button class="btn hide-mobile" data-a="speed">${speed}×</button><button class="btn ${paused?'primary':''}" data-a="pause">${paused?'▶ 继续':'Ⅱ 暂停'} <span class="key-hint">SPACE</span></button><button class="btn ${tutorial===3||tutorial===5?'guided':''}" data-a="advance">单步一拍 →</button></div></footer>${tutorial>=0?`<aside class="guide"><span class="guide-arrow">➜</span><small>实验教学 ${Math.min(tutorial+1,8)} / 8</small><strong>${guideText()[0]}</strong><p>${guideText()[1]}</p><button class="btn" data-a="skip-guide">我会了，关闭提示</button></aside>`:''}</main>`;
 const radio=$('.radio-lines');if(radio)radio.scrollTop=radio.scrollHeight;animateUnits();
}
function mapSvg(){const routes=run.jobs.filter(j=>j.status==='active').map(j=>`<path d="M50 92L50 ${j.point[1]}L${j.point[0]} ${j.point[1]}" stroke="#b9d69c" stroke-width=".35" stroke-dasharray="1 1" fill="none"/>`).join('');return `<svg class="map-grid" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="map-lines" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M5 0H0V5" fill="none" stroke="#c0d19b" stroke-width=".08" opacity=".45"/></pattern></defs><rect width="100" height="100" fill="url(#map-lines)"/><path d="M0 45H100M0 84H100M15 0V100M50 0V100M85 0V100" fill="none" stroke="#92b999" stroke-width=".15" stroke-dasharray=".8 1.2" opacity=".55"/>${routes}</svg>`;}
function actorPoint(id){const j=actorJob(run,id);if(j)return j.travelLeft?[50+(j.point[0]-50)*.5,92+(j.point[1]-92)*.5]:[j.point[0],j.point[1]+9];if(run.actors[id].returnUntil>run.turn){const h=[...run.history].reverse().find(h=>h.crew.includes(id)),q=run.jobs.find(j=>j.id===h?.id);if(q)return [(q.point[0]+50)/2,(q.point[1]+92)/2];}return [50+(run.duty.indexOf(id)-2.5)*2.5,88];}
function mapUnits(){return run.duty.map(id=>{const [x,y]=actorPoint(id);return `<span class="map-unit" data-unit="${id}" style="left:${x}%;top:${y}%" title="${who(id)}"><img src="${asset(id)}" alt=""></span>`}).join('');}
function animateUnits(){const box=$('.map-object-layer')?.getBoundingClientRect();if(!box)return;for(const el of document.querySelectorAll('[data-unit]')){const id=el.dataset.unit,pos=actorPoint(id),old=oldPositions[id];if(old&&settings.motion&&(Math.abs(pos[0]-old[0])>.2||Math.abs(pos[1]-old[1])>.2))el.animate([{translate:`${(old[0]-pos[0])*box.width/100}px ${(old[1]-pos[1])*box.height/100}px`},{translate:'0 0'}],{duration:650,easing:'ease-in-out'});oldPositions[id]=pos;}}
function openOverlay(body,kind='modal'){if(phase==='story')audio.voice?.pause();overlayKind=kind;$('#overlay').innerHTML=`<div class="backdrop"><section class="modal" role="dialog" aria-modal="true" tabindex="-1">${body}<button class="close" data-a="close" aria-label="关闭">×</button></section></div>`;$('.modal').focus();}
function closeOverlay(){const was=overlayKind;overlayKind='';$('#overlay').innerHTML='';if(was==='result'){audio.stopVoice();showPending();}else if(was==='replay'||was==='profile'){audio.stopVoice();}else if(was==='settings'&&phase==='story'){renderStory();audio.voice?.play().catch(()=>{});}}
function profile(id){const c=CHARS.find(c=>c.id===id);openOverlay(`<div class="profile"><div class="profile-art" style="--c:${c.color}"><img data-face="${id}" data-face-state="${id}" src="${asset(id)}" alt="${c.name}立绘"></div><div class="profile-info"><div class="eyebrow">PERSONNEL / ${String(CHARS.indexOf(c)+1).padStart(2,'0')}</div><h2>${c.name}</h2><div class="profile-tag">${c.title} / ${c.tags.join(' · ')}</div><div class="quote">“${c.barkText||c.quip}”</div><div class="stat-grid">${Object.entries(c.stats).map(([k,v])=>`<div><label>${STAT_NAMES[k]}<b>${v}/5</b></label><div class="stat-line"><span style="width:${v*20}%"></span></div></div>`).join('')}</div><div class="ability-box"><b>主动 · ${c.ability.name} / ${c.ability.cost}指挥点</b>${c.ability.text}</div><div class="passive">被动：${c.passive}</div><button class="btn" style="margin-top:17px" data-a="sample" data-id="${id}">▶ 听一句</button></div></div>`,'profile');}
function settingsModal(){openOverlay(`<div class="modal-body"><div class="eyebrow">AUDIO / ACCESSIBILITY</div><h2>先调到舒服的。</h2>${[['master','总音量'],['voice','角色与剧情配音'],['music','原创合成背景音乐']].map(([k,t])=>`<label class="setting-row">${t}<input type="range" min="0" max="1" step=".05" value="${settings[k]}" data-setting="${k}" aria-label="${t}"></label>`).join('')}<label class="setting-row">显示剧情字幕<input type="checkbox" data-setting="subtitles" ${settings.subtitles?'checked':''}></label><label class="setting-row">镜头运动与短动画<input type="checkbox" data-setting="motion" ${settings.motion?'checked':''}></label><p>配音为原创角色预设声线。没有真人声音克隆。<br>切到后台会暂停出警，回来后可继续。</p><div class="row"><button class="btn primary" data-a="close">保存设置</button><button class="btn" data-a="fullscreen">切换全屏 ↗</button></div></div>`,'settings');}
function help(){openOverlay(`<div class="modal-body"><div class="eyebrow">DISPATCH HANDBOOK</div><h2>不光是点人。</h2><div class="help-grid"><div><b>① 先看任务条件</b><p>点地图或任务单，选稳妥/放飞路线。能力不足会失败；情报不全的任务可侦察。</p></div><div><b>② 别把人全派远</b><p>出发1拍，工作若干拍，再返程。疲劳3会削弱属性，6必须休息。</p></div><div><b>③ 主动技能真有用</b><p>点角色卡下面的技能，作用于当前任务。部分技能须先到现场；回溯和复核作用于全局。</p></div><div><b>④ 资源需要分配</b><p>工具可花3预算采购。指挥点每3拍恢复1点；升级休息室能改善后勤。</p></div><div><b>⑤ 前置和干扰</b><p>某些任务要先修供电或设备。放飞方案有时可绕过前置。王字如能挡住系统恶化。</p></div><div><b>⑥ 过关与三星</b><p>达到完成数量并处理全部关键任务才过关。三星还要求全清、低损失和低压力。</p></div></div><p>空格：暂停/继续　N：单步一拍　Esc：暂停菜单<br>所有暂停状态都可以规划、派人、采购和使用技能。</p><div class="row"><button class="btn primary" data-a="close">继续干活</button>${phase==='play'?'<button class="btn" data-a="buy-tool">买1工具 / 3预算</button>':''}</div></div>`,'help');}
function pauseMenu(){paused=true;renderPlay();openOverlay(`<div class="modal-body"><div class="eyebrow">TACTICAL PAUSE</div><h2>先喘口气。</h2><p>时间已暂停。正常返程和任务期限都不会继续走。</p><div style="display:grid;gap:10px"><button class="btn primary" data-a="resume">继续出警</button><button class="btn" data-a="settings">声音与设置</button><button class="btn" data-a="help">操作手册 / 采购工具</button><button class="btn" data-a="retry">重新排这一班</button><button class="btn" data-a="end-run">现在结算本班</button><button class="btn ghost" data-a="save-menu">保存并回主菜单</button></div></div>`,'pause');}
function resultPanel(r,replay=false){resultRecord=r;const painted=run.level===0?'intro-office':r.success&&['lift','fire'].includes(r.type)?`scene-${r.type}-${r.mode}`:LEVELS[run.level].image;openOverlay(`<div class="result-top"><div><div class="eyebrow">FIELD REPORT / ${clock(r.at)}</div><h2>${esc(r.title)}</h2></div><span class="result-stamp ${r.success?'':'fail'}">${r.success?'活干完了':'这波寄了'}</span></div><div class="result-art"><img src="${asset(painted)}" alt="${r.success?'成功':'失败'}的漫画现场"><div class="result-portraits">${r.crew.map(id=>`<img data-face="${id}" data-face-state="${id}" src="${asset(id)}" alt="${who(id)}">`).join('')}</div><div class="result-caption">${r.success?(r.damage?'人没事，设备有点事。':'这单居然没赔钱。'):'别嘴硬了，先看复盘。'}</div></div><div class="dialogue">${r.lines.map(([id,t])=>`<div class="speech"><b>${who(id)}</b><span>${esc(t)}</span></div>`).join('')}</div><div class="result-footer"><small>奖金 +${r.pay} / 设备损失 ${r.damage}<br>人员要返程并恢复疲劳，才能再次出勤。</small><button class="btn primary" data-a="${replay?'close-replay':'close'}">${replay?'关掉回放':'继续派遣'} →</button></div>`,replay?'replay':'result');audio.fx(r.success?'success':'fail');}
function showPending(){if(pending.length){const r=pending.shift();resultPanel(r);return;}if(run?.finished){finishStage();return;}if(phase==='play')renderPlay();}
function handleOutput(out){
 const results=out.filter(x=>x.kind==='result');const event=out.find(x=>x.kind==='event');const arrivals=out.find(x=>x.kind==='arrival');
 if(event)toast(event.text);else if(arrivals)toast('新来电：'+arrivals.text);else if(out.find(x=>x.kind==='rewind'))toast('已回到上一拍。刚才那波不算。');
 pending.push(...results);renderPlay();save();if(pending.length)showPending();else if(run.finished)finishStage();
}
function advance(){if(phase!=='play'||overlayKind||!run?.started||run.finished)return;beatElapsed=0;audio.fx('turn');const out=tick(run);if(tutorial===3&&run.turn>=1)tutorial=4;if(tutorial===5&&run.turn>=3){tutorial=6;selectedJob='lab-crate';}handleOutput(out);}
function launch(){const error=start(run);if(error){toast(error);return;}paused=run.level===0;beatElapsed=0;phase='play';crew=[];selectedJob=run.jobs[0].id;route='safe';audio.init();audio.fx('send');renderPlay();save();}
function finishStage(){if(phase==='debrief')return;clearTimeout(toastTimer);$('#toast').classList.remove('show');paused=true;audio.stopVoice();if(run.passed){stageReward=commitWin(campaign,run);audio.fx('success');}else{stageReward={reward:0,stars:0};campaign.run=structuredClone({...run,checkpoint:null});audio.play('debrief-fail');}phase='debrief';overlayKind='';$('#overlay').innerHTML='';renderDebrief();save();}
function renderDebrief(){const l=LEVELS[run.level],stars=rating(run),next=LEVELS[Math.min(run.level+1,5)],newChars=next.unlock.filter(id=>!l.unlock.includes(id));$('#game').innerHTML=`<main class="screen debrief"><div class="debrief-grid"><section><div class="eyebrow">${l.district} / ${run.passed?'CASE CLOSED':'TRY AGAIN'}</div><h1>${run.passed?(stars===3?'这班，漂亮。':'人没事，账单有事。'):'锅没甩掉，<br>再排一次。'}</h1><div class="stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p class="lede">${run.passed?'目标完成，档案可以销了。下一个片区已经开始催单。':'复盘重点：是否错过期限、被前置卡住，或把需要的人派远了？换路线、用技能、买工具，都能改变结果。'}${run.panic>=100?' 城市压力已达到100。':''}</p><div class="score-row"><div><b>${run.completed}/${run.jobs.length}</b><span>处理完成</span></div><div><b>${run.damage}</b><span>设备损失</span></div><div><b>${run.budget}</b><span>剩余预算</span></div><div><b>+${stageReward?.reward||0}</b><span>本次津贴</span></div></div>${newChars.length&&run.passed?`<div class="unlock-banner">新队员接入：${newChars.map(who).join('、')}。下一关可以选择他们，并使用新的主动技能。</div>`:''}<div class="case-results">${run.jobs.map(j=>`<div class="case-result"><span class="${j.status==='done'?'good':'bad'}">${j.status==='done'?'✓':'×'}</span><span>${j.critical?'! ':''}${esc(j.title)}</span><span class="small">${taskLabel(j)}</span>${run.history.some(x=>x.id===j.id)?`<button data-a="replay" data-id="${j.id}">现场回放 ↗</button>`:''}</div>`).join('')}</div><div class="debrief-actions">${run.passed?`<button class="btn primary big" data-a="${run.level===5?'ending':'next-level'}">${run.level===5?'看天亮之后':'下一关，接着整'} →</button>`:''}<button class="btn" data-a="retry">重排这一班</button><button class="btn ghost" data-a="chapters">关卡档案 / 休息室</button></div><p class="small">${stars===3?'三星记录已保存。':`三星要求：全部处理、损失≤${Math.max(2,run.level+1)}、城市压力<25。`} 重玩只发新增星级的津贴。</p></section><aside class="debrief-card"><img src="${asset(run.passed?l.image:'intro-office')}" alt="班次复盘漫画"><div><div class="eyebrow">DISPATCH OFFICE / INTERNAL NOTE</div><h3>${run.passed?'先把报销单收好。':'会已经给你约好了。'}</h3><p>${run.passed?'嘴硬不算能力，真把人和事处理好才算。下班之前，记得去休息室看看能不能改善一下后勤。':'失败任务若还有时间，罗咏皓可以兜底接回。情报不全就侦察；时间不够就赶工；系统要搞事，就先做复核。'}</p></div></aside></div></main>`;}
function ending(){beginStory(ENDING,()=>{phase='credits';render();save();},'尾声：天亮以后');}
function renderCredits(){const stars=campaign.stars.reduce((n,x)=>n+x,0);$('#game').innerHTML=`<main class="screen menu credits-screen"><img class="menu-bg" src="${asset('ending-city')}" alt="天亮后的抽象区"><div class="menu-shade"></div><div class="menu-content"><div class="eyebrow">ALL CASES CLOSED / 06 OF 06</div><h1 class="menu-title">天亮了。<br><span>下班吧。</span></h1><div class="menu-sub">派遣局保住了，今晚的锅也背完了。<br>战役完成 · ${stars} / 18 颗星</div><div class="menu-actions"><button class="menu-button primary" data-a="chapters">重玩关卡 / 休息室 <small>CASE FILES →</small></button><button class="menu-button" data-a="ending">再看一次尾声 <small>REPLAY</small></button><button class="menu-button" data-a="menu">返回主菜单 <small>MENU</small></button></div></div><div class="end-credits"><div class="eyebrow">THE NIGHT SHIFT / CREDITS</div><h2>人很好，下次轻点。</h2><p>原创战役、游戏代码与动态漫画演出<br>美漫人物与背景：内置图像生成工具<br>中文剧情与角色声音：ElevenLabs 预设声线<br>背景音乐与提示音：原创合成音</p><p>感谢你撑过这一晚。</p></div></main>`;}
function continueCampaign(){audio.init();if(campaign.run&&!campaign.run.finished){run=structuredClone(campaign.run);run.checkpoint=null;phase='play';paused=true;crew=[];selectedJob=run.jobs.find(j=>['waiting','locked','active'].includes(j.status))?.id||run.jobs[0].id;route='safe';tutorial=run.level===0&&campaign.stars[0]===0&&Number.isInteger(run.uiTutorial)?run.uiTutorial:-1;if(run.jobs.some(j=>j.id===run.uiJob))selectedJob=run.uiJob;renderPlay();}else if(campaign.run?.finished){run=structuredClone(campaign.run);stageReward={reward:0,stars:0};phase='debrief';renderDebrief();}else{setPhase('chapters');}}
function act(el){const a=el.dataset.a,id=el.dataset.id;audio.init();
 if(a==='new'){if(campaign.stars.some(n=>n)||campaign.run){openOverlay(`<div class="modal-body"><h2>重新开一个夜班档案？</h2><p>这会重置当前战役进度和游戏内改造。声音设置保留。</p><div class="row"><button class="btn primary" data-a="new-confirm">开新档</button><button class="btn" data-a="close">先留着</button></div></div>`,'confirm');}else beginNew();return;}
 if(a==='new-confirm'){beginNew();return;}if(a==='continue'){continueCampaign();return;}if(a==='menu'){menu();return;}if(a==='save-menu'){save();menu();return;}
 if(a==='chapters'){save();run=null;setPhase('chapters');return;}if(a==='chapter'){chooseChapter(Number(el.dataset.level));return;}
 if(a==='upgrade'){const e=buyUpgrade(campaign,id);if(e)toast(e);else{audio.fx('success');toast('改造装好了，下关生效。');}renderChapters();save();return;}
 if(a==='roster'){if(run.duty.includes(id))run.duty=run.duty.filter(x=>x!==id);else if(run.duty.length<LEVELS[run.level].squad)run.duty.push(id);else{toast('先让一位休班，再换他上来。');return;}audio.fx('click');renderPrep();return;}
 if(a==='difficulty'){difficulty=el.dataset.mode;const duty=[...run.duty];run=newRun(run.level,campaign,difficulty);run.duty=duty;renderPrep();return;}
 if(a==='launch'){launch();return;}if(a==='settings'){settingsModal();return;}if(a==='help'){help();return;}if(a==='profile'){profile(id);return;}if(a==='sample'){audio.play('bark-'+id);return;}
 if(a==='close'){closeOverlay();return;}if(a==='close-replay'){overlayKind='';$('#overlay').innerHTML='';audio.stopVoice();return;}
 if(a==='next-story'){nextStory();return;}if(a==='skip-story'){skipStory();return;}if(a==='ending'){ending();return;}
 if(a==='next-level'){chooseChapter(Math.min(5,run.level+1));return;}if(a==='retry'){const lv=run.level;chooseChapter(lv,false);return;}
 if(a==='pause-menu'){pauseMenu();return;}if(a==='resume'){overlayKind='';$('#overlay').innerHTML='';paused=false;beatElapsed=0;renderPlay();return;}
 if(a==='pause'){paused=!paused;beatElapsed=0;audio.fx('click');renderPlay();return;}if(a==='speed'){speed=speed===1?2:1;renderPlay();return;}if(a==='advance'){advance();return;}
 if(a==='end-run'){finishNow(run);overlayKind='';$('#overlay').innerHTML='';finishStage();return;}
 if(a==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.();return;}
 if(a==='skip-guide'){tutorial=-1;renderPlay();return;}
 if(a==='job'){selectedJob=id;crew=[];if(tutorial===0&&id==='lab-door')tutorial=1;audio.fx('click');renderPlay();return;}
 if(a==='crew'){
  if(!available(run,id)){toast(who(id)+'现在'+actorState(id)+'。');return;}
  if(crew.includes(id))crew=crew.filter(x=>x!==id);else if(crew.length<2)crew.push(id);else{toast('每单最多2人。先取消一位。');return;}
  if(tutorial===1&&id==='he')tutorial=2;if(tutorial===6&&id==='geng')tutorial=7;audio.fx('click');renderPlay();return;
 }
 if(a==='route'){route=el.dataset.mode;audio.fx('click');renderPlay();return;}
 if(a==='dispatch'){
  const r=dispatch(run,selectedJob,crew,route);if(r.error){toast(r.error);return;}if(tutorial===2)tutorial=3;crew=[];audio.fx('send');run.log.push({at:run.turn,who:r.job.crew[0],text:CHARS.find(c=>c.id===r.job.crew[0]).barkText});audio.play('bark-'+r.job.crew[0]);renderPlay();save();return;
 }
 if(a==='recall'){const e=recall(run,id);if(e)toast(e);else{toast('队员已召回，费用和工具不退。');renderPlay();save();}return;}
 if(a==='skill'){
  const r=skill(run,id,selectedJob);if(r.error){toast(r.error);return;}if(tutorial===4&&id==='he'){tutorial=5;selectedJob='lab-door';}audio.fx('skill');run.log.push({at:run.turn,who:id,text:CHARS.find(c=>c.id===id).barkText});audio.play('bark-'+id);crew=crew.filter(c=>available(run,c));beatElapsed=0;handleOutput(r.out);return;
 }
 if(a==='buy-tool'){const e=buyTools(run);if(e)toast(e);else{audio.fx('click');toast('工具包+1，预算-3。');if(phase==='play')renderPlay();save();}return;}
 if(a==='replay'){const r=[...run.history].reverse().find(r=>r.id===id);if(r)resultPanel(r,true);return;}
}
function beginNew(){campaign=newCampaign();audio.init();overlayKind='';$('#overlay').innerHTML='';campaign.seenIntro=true;save();beginStory(OPENING,()=>chooseChapter(0), '序幕：今晚谁背锅');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(el&&!el.disabled)act(el);else if(e.target.classList.contains('backdrop'))closeOverlay();});
document.addEventListener('input',e=>{const k=e.target.dataset.setting;if(!k)return;settings[k]=e.target.type==='checkbox'?e.target.checked:Number(e.target.value);audio.update();document.documentElement.classList.toggle('reduce-motion',!settings.motion);save();});
document.addEventListener('keydown',e=>{
 if(e.target.matches('input,textarea,select'))return;
 if(overlayKind){if(e.key==='Escape'){e.preventDefault();closeOverlay();}if(e.key==='Tab'){const list=[...$('.modal').querySelectorAll('button:not(:disabled),input')];if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){e.preventDefault();first.focus();}}return;}
 if(phase==='story'&&e.code==='Space'){e.preventDefault();nextStory();return;}
 if(phase==='play'){if(e.code==='Space'){e.preventDefault();paused=!paused;beatElapsed=0;renderPlay();}else if(e.code==='KeyN'){e.preventDefault();advance();}else if(e.key==='Escape'){e.preventDefault();pauseMenu();}}
});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(phase==='play'){paused=true;renderPlay();}audio.voice?.pause();}else if(phase==='story'&&audio.voice)audio.voice.play().catch(()=>{});lastFrame=performance.now();});
function captionAt(p,elapsed){const parts=p.text.match(/[^\u3002\uff01\uff1f]+[\u3002\uff01\uff1f]?/g)||[p.text];const total=parts.reduce((n,x)=>n+x.length,0);const fraction=Math.min(.999,Math.max(0,elapsed/Math.max(1,storyDuration-.8)));let used=0;for(const part of parts){used+=part.length;if(used>=total*fraction)return part;}return parts.at(-1);}
let facesActive=false;
function performFaces(){const a=audio.voice,id=audio.voiceId?.replace('bark-','');const acting=!!a&&!a.paused&&!a.ended&&['tim','da'].includes(id);if(!acting&&!facesActive)return;facesActive=acting;for(const actor of ['tim','da']){let key=actor;if(acting&&actor===id){const f=Number.isFinite(a.duration)&&a.duration>0?a.currentTime/a.duration:0;key=actor==='tim'?(f<.52?'tim-excited':'tim-focused'):(f<.48?'da-nervous':'da-defensive');}for(const image of document.querySelectorAll('[data-face="'+actor+'"]'))if(image.dataset.faceState!==key){image.dataset.faceState=key;image.src=asset(key);}}}
function frame(now){performFaces();const dt=Math.min(.15,(now-lastFrame)/1000);lastFrame=now;
 if(!document.hidden&&!overlayKind){
  if(phase==='story'&&story){storyTime+=dt;const caption=$('#story-text'),text=captionAt(story[storyIndex],audio.voice?.currentTime||storyTime);if(caption&&caption.textContent!==text){caption.textContent=text;caption.classList.remove('caption-in');requestAnimationFrame(()=>caption.classList.add('caption-in'));}const seg=document.querySelectorAll('.story-segment')[storyIndex];if(seg)seg.style.width=Math.min(100,storyTime/storyDuration*100)+'%';if(storyTime>=storyDuration)nextStory();}
  if(phase==='play'&&run?.started&&!run.finished&&!paused){beatElapsed+=dt*speed;const m=$('#beat-meter');if(m)m.style.width=Math.min(100,beatElapsed/6*100)+'%';if(beatElapsed>=6)advance();}
 }
 requestAnimationFrame(frame);
}
render();requestAnimationFrame(frame);
